SELECT * FROM (SELECT DATE_TRUNC('MONTH', last_restock) AS last_restock_month, CASE WHEN quantity >= 184 THEN 'high' WHEN quantity >= 91 THEN 'mid' ELSE 'low' END AS quantity_bucket, SUM(quantity) AS total_quantity FROM inventory GROUP BY DATE_TRUNC('MONTH', last_restock), CASE WHEN quantity >= 184 THEN 'high' WHEN quantity >= 91 THEN 'mid' ELSE 'low' END) AS agg WHERE total_quantity > 410 ORDER BY quantity_bucket, last_restock_month LIMIT 10;
